CREATE EXTENSION IF NOT EXISTS pgcrypto; CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),role text NOT NULL CHECK(role IN('admin','faculty','student')),login_id text NOT NULL UNIQUE,password_hash text NOT NULL,full_name text NOT NULL,email text,prn text UNIQUE,roll_number text,section text,is_active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now()); CREATE TABLE IF NOT EXISTS subjects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE,name text NOT NULL,semester text,section text,is_active boolean DEFAULT true); CREATE TABLE IF NOT EXISTS faculty_subjects(faculty_id uuid REFERENCES users(id),subject_id uuid REFERENCES subjects(id),PRIMARY KEY(faculty_id,subject_id)); CREATE TABLE IF NOT EXISTS student_subjects(student_id uuid REFERENCES users(id),subject_id uuid REFERENCES subjects(id),PRIMARY KEY(student_id,subject_id)); CREATE TABLE IF NOT EXISTS assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_id uuid REFERENCES subjects(id),faculty_id uuid REFERENCES users(id),title text NOT NULL,due_at timestamptz NOT NULL,allow_late boolean DEFAULT false,late_due_at timestamptz,allow_resubmission boolean DEFAULT true,status text DEFAULT 'published'); CREATE TABLE IF NOT EXISTS submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assignment_id uuid REFERENCES assignments(id),student_id uuid REFERENCES users(id),current_version int DEFAULT 1,status text DEFAULT 'submitted',marks numeric(7,2),max_marks numeric(7,2),feedback text,UNIQUE(assignment_id,student_id)); CREATE TABLE IF NOT EXISTS submission_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid REFERENCES submissions(id),version_number int NOT NULL,file_name text NOT NULL,file_base64 text,mime_type text NOT NULL,file_size bigint NOT NULL,submitted_at timestamptz DEFAULT now(),submitted_late boolean DEFAULT false,UNIQUE(submission_id,version_number)); CREATE TABLE IF NOT EXISTS quizzes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_id uuid REFERENCES subjects(id),faculty_id uuid REFERENCES users(id),title text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,duration_minutes int DEFAULT 30,status text DEFAULT 'published'); CREATE TABLE IF NOT EXISTS quiz_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quiz_id uuid REFERENCES quizzes(id),question_text text NOT NULL,options jsonb NOT NULL,correct_option int NOT NULL,marks numeric(7,2) DEFAULT 1); CREATE TABLE IF NOT EXISTS quiz_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quiz_id uuid REFERENCES quizzes(id),student_id uuid REFERENCES users(id),score numeric(7,2) DEFAULT 0,max_score numeric(7,2) DEFAULT 0,submitted_at timestamptz); CREATE TABLE IF NOT EXISTS quiz_answers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid REFERENCES quiz_attempts(id),question_id uuid REFERENCES quiz_questions(id),selected_option int,is_correct boolean,awarded_marks numeric(7,2)); CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,details jsonb DEFAULT '{}'::jsonb,created_at timestamptz DEFAULT now());